<?php declare(strict_types=1); ?>
<div class="mod-wrap"><form method="post" action="<?= $v->url('mod.php') ?>"><?= $v->csrf() ?><input type="hidden" name="action" value="settings"><fieldset><legend>Site appearance</legend><label>Site title <input name="title" maxlength="100" value="<?= $v::e($v->app->setting('title', $v->app->config->string('title'))) ?>" required></label><label>Default theme <select name="theme"><?php foreach ($v->themes() as $key => $label): ?><option value="<?= $v::e($key) ?>" <?= $v->app->setting('theme', $v->app->config->string('theme')) === $key ? 'selected' : '' ?>><?= $v::e($label) ?></option><?php endforeach ?></select></label><button>Save and rebuild</button></fieldset></form></div>
